import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
// 2026-10-06 (#a5decf4a): у фрагмента, утверждённого в админке, вместо «הטקסט עדיין לא אושר…» — «מקור: … · אושר על ידי …».
import { SOURCE_LINE } from '../_helpers/prayer-nav';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 1440, height: 900 },
});

const PRAYERS: Array<[string, number]> = [
  ['shacharit_ashkenaz', 66],
  ['shacharit_sfarad', 57],
  ['mincha_ashkenaz', 8],
  ['mincha_sfarad', 11],
  ['arvit_ashkenaz', 15],
  ['arvit_sfarad', 16],
];

const counterLocator = (page: Page) => page.getByText(/^\d+ מתוך \d+$/).first();

async function readCounter(page: Page): Promise<[number, number]> {
  const m = (await counterLocator(page).innerText()).match(/(\d+) מתוך (\d+)/)!;
  return [Number(m[1]), Number(m[2])];
}

async function rewindToFirst(page: Page) {
  for (;;) {
    const [i, n] = await readCounter(page);
    if (i === 1) return n;
    await page.getByRole('button', { name: 'קודם', exact: true }).click();
    await expect(counterLocator(page)).toHaveText(`${i - 1} מתוך ${n}`);
  }
}

test.describe('Молитва по шагам', () => {
  test('GP-05 Пояснение #runner-section-info и строка источника во всех фрагментах основных молитв #6a86f7df @prod-safe @desktop', async ({ page }) => {
    // 1. test.slow(). Сохранить localStorage['prayer-progress'].
    test.slow();
    test.setTimeout(900_000);
    await page.goto('/home');
    await expect(page.getByRole('button', { name: 'התחל תפילה' })).toBeVisible({ timeout: 20_000 });
    const saved = await page.evaluate(() => localStorage.getItem('prayer-progress'));
    try {
      for (const [key, total] of PRAYERS) {
        // 2. Открыть /prayer/<key>; «קודם» до «1 מתוך N».
        await page.goto(`/prayer/${key}`);
        await expect(counterLocator(page)).toBeVisible({ timeout: 20_000 });
        const n = await rewindToFirst(page);
        expect(n, `${key}: число фрагментов`).toBe(total);
        await expect(counterLocator(page)).toHaveText(`1 מתוך ${total}`);

        // 3. На каждом фрагменте проверить пояснение и строку источника; «המשך» до «N מתוך N».
        for (let i = 1; i <= total; i++) {
          await expect(counterLocator(page), `${key}`).toHaveText(`${i} מתוך ${total}`);
          const info = page.locator('#runner-section-info');
          await expect(info, `${key} ${i}/${total}: #runner-section-info`).toBeVisible();
          await expect(page.locator('#runner-section-info-text'), `${key} ${i}/${total}: текст пояснения`).not.toHaveText('');
          await expect(info.locator('svg').first(), `${key} ${i}/${total}: иконка ⓘ`).toBeVisible();
          const source = page.getByText(SOURCE_LINE);
          await expect(source, `${key} ${i}/${total}: строка источника`).toHaveCount(1);
          const infoBox = (await info.boundingBox())!;
          const srcBox = (await source.boundingBox())!;
          expect(srcBox.y, `${key} ${i}/${total}: источник под пояснением`).toBeGreaterThanOrEqual(infoBox.y + infoBox.height - 1);
          if (i < total) {
            await page.getByRole('button', { name: 'המשך', exact: true }).click();
          }
        }
      }
    } finally {
      // 4. Уборка: вернуть сохранённое значение prayer-progress.
      await page.goto('/home');
      await page.evaluate((v) => {
        if (v === null) localStorage.removeItem('prayer-progress');
        else localStorage.setItem('prayer-progress', v);
      }, saved);
    }
  });
});
